public Direction SelectedConnectionDirection { get => SelectedConnection?.Direction ?? Direction.North; set { if (SelectedConnection != null) { var oldDir = SelectedConnection.Direction; var oldRev = SelectedConnection.ReverseDirection; SelectedConnection.Direction = value; SelectedConnection.ReverseDirection = DirectionHelper.GetReverseDirection(value); MarkDirty(); OnPropertyChanged(); PushUndo("Change Direction", () => { SelectedConnection.Direction = oldDir; SelectedConnection.ReverseDirection = oldRev; MarkDirty(); OnPropertyChanged(); }); } } }